import {POWER_PLANTS,POWER_WASTE} from './power.js?v=architecture-collection-36';
import {wasteProduction} from './utilities.js?v=architecture-collection-36';
export function infrastructureWasteSources(c){return c.tiles.filter(t=>t.type==='recycling'||POWER_WASTE[t.type]&&t.root===t.y*c.size+t.x).map(t=>{let waiting=0;if(t.type==='recycling')waiting=t.waste||0;else for(let y=t.y;y<t.y+POWER_PLANTS[t.type].size;y++)for(let x=t.x;x<t.x+POWER_PLANTS[t.type].size;x++){const u=c.tiles[y*c.size+x];if(u?.root===t.root)waiting+=u.waste||0;}return{root:t.root,x:t.x,y:t.y,type:t.type,name:POWER_PLANTS[t.type]?.name||'Recycling center',rate:wasteProduction(t,c),waiting};});}
export function infrastructureGarbageInspection(c,t){if(!POWER_WASTE[t.type]&&t.type!=='recycling')return '';const source=infrastructureWasteSources(c).find(s=>s.type===t.type&&(t.type==='recycling'?s.x===t.x&&s.y===t.y:s.root===t.root));return source?`<p>Garbage: ${source.rate.toFixed(2)} units/month · ${source.waiting.toFixed(2)} waiting. Connect roads beside the facility to disposal or garbage export. Power plants use access beside their whole footprint. Recycling reduces eligible new waste but still leaves residue needing disposal.</p>`:'';}
export function infrastructureWasteReport(c){const sources=infrastructureWasteSources(c);if(!sources.length)return '';const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});return `<details><summary>Power and recycling · garbage</summary><p>These facilities produce ${fmt(sources.reduce((n,s)=>n+s.rate,0))} units/month, included in city garbage production. Intact power plants generate waste even with no road; operating recycling centers generate waste while powered and road-connected.</p><div class="table-scroll"><table aria-label="Infrastructure garbage"><thead><tr><th>Facility</th><th>Units/month</th><th>Waiting</th></tr></thead><tbody>${sources.map(s=>`<tr><th scope="row">${s.name} · ${s.x+1}, ${s.y+1}</th><td>${fmt(s.rate)}</td><td>${fmt(s.waiting)}</td></tr>`).join('')}</tbody></table></div><p>Wind and solar plants add no garbage. Waste from other plants is charged once per building, regardless of footprint size or electrical load. Existing waste remains until collected.</p></details>`;}
